using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.EntityFrameworkCore.Migrations.Operations;

namespace Mapepire.EntityFrameworkCore.Tests;

/// <summary>Offline tests for DDL generated by migrations and EnsureCreated.</summary>
[TestClass]
public sealed class MigrationSqlTests
{
    private static string CreateScript()
    {
        using var context = BloggingContext.CreateOffline();
        var script = context.Database.GenerateCreateScript();
        Console.WriteLine(script);
        return script;
    }

    private static string Generate(params MigrationOperation[] operations)
    {
        using var context = BloggingContext.CreateOffline();
        var generator = context.GetService<IMigrationsSqlGenerator>();
        var commands = generator.Generate(operations, context.GetService<IDesignTimeModel>().Model);
        var sql = string.Join(Environment.NewLine, commands.Select(c => c.CommandText));
        Console.WriteLine(sql);
        return sql;
    }

    [TestMethod]
    public void Integer_key_is_identity()
        => StringAssert.Contains(CreateScript(), "\"Id\" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 1, INCREMENT BY 1)");

    [TestMethod]
    public void Guid_key_is_char36_and_not_identity()
    {
        var script = CreateScript();
        StringAssert.Contains(script, "\"Id\" CHAR(36) NOT NULL,");
    }

    [TestMethod]
    public void Column_types_and_nullability()
    {
        var script = CreateScript();
        StringAssert.Contains(script, "\"Name\" NVARCHAR(100) NOT NULL");
        StringAssert.Contains(script, "\"IsActive\" SMALLINT NOT NULL");
        StringAssert.Contains(script, "\"Rating\" DECIMAL(18,2),");
        StringAssert.Contains(script, "\"CreatedAt\" TIMESTAMP NOT NULL");
        StringAssert.Contains(script, "\"Content\" NVARCHAR(4000),");
        StringAssert.Contains(script, "\"PublishedOn\" DATE,");
        Assert.IsFalse(System.Text.RegularExpressions.Regex.IsMatch(script, @"(?<!NOT) NULL\s*[,)]"),
            "Db2 for i does not accept a bare NULL column attribute");
    }

    [TestMethod]
    public void Foreign_key_and_indexes()
    {
        var script = CreateScript();
        StringAssert.Contains(script, "FOREIGN KEY (\"BlogId\") REFERENCES \"Blogs\" (\"Id\") ON DELETE CASCADE");
        StringAssert.Contains(script, "CREATE UNIQUE INDEX \"IX_Blogs_Name\" ON \"Blogs\" (\"Name\")");
        StringAssert.Contains(script, "CREATE INDEX \"IX_Posts_PublishedOn\" ON \"Posts\" (\"PublishedOn\")");
    }

    [TestMethod]
    public void Unique_index_on_nullable_column_ignores_nulls()
    {
        var sql = Generate(new CreateIndexOperation
        {
            Name = "IX_Posts_PublishedOn_U",
            Table = "Posts",
            Columns = ["PublishedOn"],
            IsUnique = true,
        });
        StringAssert.Contains(sql, "CREATE UNIQUE WHERE NOT NULL INDEX");
    }

    [TestMethod]
    public void Index_in_schema_is_qualified()
    {
        var sql = Generate(new CreateIndexOperation { Name = "IX_T", Schema = "LIB", Table = "T", Columns = ["C"] });
        StringAssert.Contains(sql, "CREATE INDEX \"LIB\".\"IX_T\" ON \"LIB\".\"T\" (\"C\")");
    }

    [TestMethod]
    public void Ensure_schema_ignores_existing_schema()
    {
        var sql = Generate(new EnsureSchemaOperation { Name = "LIB" });
        StringAssert.Contains(sql, "DECLARE CONTINUE HANDLER FOR SQLSTATE '42710'");
        StringAssert.Contains(sql, "EXECUTE IMMEDIATE 'CREATE SCHEMA \"LIB\"'");
    }

    [TestMethod]
    public void Rename_and_drop_operations()
    {
        var sql = Generate(
            new RenameTableOperation { Name = "A", Schema = "LIB", NewName = "B" },
            new RenameIndexOperation { Name = "IX_A", Schema = "LIB", Table = "B", NewName = "IX_B" },
            new DropIndexOperation { Name = "IX_B", Schema = "LIB", Table = "B" },
            new RenameColumnOperation { Table = "B", Schema = "LIB", Name = "X", NewName = "Y" });
        StringAssert.Contains(sql, "RENAME TABLE \"LIB\".\"A\" TO \"B\"");
        StringAssert.Contains(sql, "RENAME INDEX \"LIB\".\"IX_A\" TO \"IX_B\"");
        StringAssert.Contains(sql, "DROP INDEX \"LIB\".\"IX_B\"");
        StringAssert.Contains(sql, "ALTER TABLE \"LIB\".\"B\" RENAME COLUMN \"X\" TO \"Y\"");
    }

    [TestMethod]
    public void Alter_column_type_nullability_and_default()
    {
        var sql = Generate(new AlterColumnOperation
        {
            Table = "T",
            Name = "C",
            ClrType = typeof(string),
            ColumnType = "NVARCHAR(200)",
            IsNullable = false,
            DefaultValue = "x",
            OldColumn = new AddColumnOperation { Table = "T", Name = "C", ClrType = typeof(string), ColumnType = "NVARCHAR(100)", IsNullable = true },
        });
        StringAssert.Contains(sql, "ALTER TABLE \"T\" ALTER COLUMN \"C\" SET DATA TYPE NVARCHAR(200)");
        StringAssert.Contains(sql, "ALTER TABLE \"T\" ALTER COLUMN \"C\" SET NOT NULL");
        StringAssert.Contains(sql, "ALTER TABLE \"T\" ALTER COLUMN \"C\" SET DEFAULT 'x'");
    }

    [TestMethod]
    public void Date_default_is_plain_constant()
    {
        var sql = Generate(new AddColumnOperation
        {
            Table = "T",
            Name = "D",
            ClrType = typeof(DateTime),
            ColumnType = "TIMESTAMP",
            DefaultValue = new DateTime(2000, 1, 2),
        });
        StringAssert.Contains(sql, "DEFAULT '2000-01-02-00.00.00.000000'");
    }

    [TestMethod]
    public void Computed_columns_are_rejected()
        => Assert.ThrowsException<NotSupportedException>(() => Generate(new AddColumnOperation
        {
            Table = "T",
            Name = "C",
            ClrType = typeof(int),
            ComputedColumnSql = "A + B",
        }));
}
